  async function loadNextStudyQuestion() {
    if (!studyContext || studyLoading) return;
    studyLoading = true;
    try { const result = await onNextStudyQuestion(studyContext.positions || []); studyQuestion = result?.question || null; studyProgress = Number(result?.points) || 0; }
    catch (error) { studyQuestion = { error: error?.message || "Could not load a study question." }; }
    finally { studyLoading = false; if (activeView === "study") render("study"); }
  }
  function renderStudySession() {
    const wrap = el("div", "study-session");
    wrap.innerHTML = `<div class="study-session-header"><button type="button">← Learning Labs</button><div><span>${studyContext?.chapterLabel || "Current chapter"}</span><h2>${studyContext?.sphere || "Orbital"} Expedition</h2></div><em>Adaptive review</em></div><div class="study-mastery" role="progressbar" aria-label="Study progress" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${studyProgress}"><i style="width:${studyProgress * 10}%"></i></div><section class="study-question-card"><span>ARCHIVE PROMPT</span><h3></h3><div class="study-answer-grid"></div><p class="study-feedback">Fill the bar with correct answers. An incorrect answer removes three steps.</p></section>`;
    wrap.querySelector(".study-session-header button").addEventListener("click", () => render("simulations"));
    const heading = wrap.querySelector("h3"); const answers = wrap.querySelector(".study-answer-grid");
    if (studyLoading || !studyQuestion) { heading.textContent = "Retrieving the next archive question…"; return wrap; }
    if (studyQuestion.error || !studyQuestion.id) { heading.textContent = studyQuestion.error || "No questions are available for the ship’s current position."; wrap.querySelector(".study-feedback").textContent = "Ask your teacher to add or activate a question set for this chapter."; return wrap; }
    heading.textContent = studyQuestion.prompt;
    if (!studyQuestion.answerOrder) studyQuestion.answerOrder = (studyQuestion.answers || []).map((answer, originalIndex) => ({ answer, originalIndex })).sort(() => Math.random() - .5);
    studyQuestion.answerOrder.forEach(({ answer, originalIndex }) => { const button = el("button", "study-answer", answer); button.type = "button"; button.addEventListener("click", async () => { const feedback = wrap.querySelector(".study-feedback"); wrap.querySelectorAll(".study-answer").forEach((entry) => { entry.disabled = true; }); try { const result = await onAnswerStudyQuestion({ questionId: studyQuestion.id, selectedIndex:originalIndex, sphere:studyContext.sphere }); studyProgress = Number(result?.points) || 0; button.classList.add(result?.correct ? "correct" : "wrong"); feedback.textContent = result?.inventoryFull ? "Mastery recorded, but the sample was lost because your inventory is full." : result?.reward ? "Mastery achieved! The prize wheel is awarding your sample. Your bar has restarted." : result?.correct ? "Correct. The mastery signal increased." : "Incorrect. The mastery signal dropped three steps."; if(result?.inventoryFull)window.alert("Inventory full — the sample could not be stored, but your archive completion and progress were recorded."); window.setTimeout(() => { studyQuestion = null; render("study"); loadNextStudyQuestion(); }, result?.reward ? 2400 : 900); } catch (error) { feedback.textContent = error?.message || "The answer could not be recorded."; wrap.querySelectorAll(".study-answer").forEach((entry) => { entry.disabled = false; }); } }); answers.appendChild(button); });
    return wrap;
  }
